    /// family -> what that family accepts on a request.
    static let families: [String: ModelFamilySpec] = {
        guard let data = json.data(using: .utf8) else { return [:] }
        return (try? JSONDecoder().decode([String: ModelFamilySpec].self, from: data)) ?? [:]
    }()

    /// Resolve a model id to its family.
    ///
    /// `make-server-config.sh` names every model after its family exactly (adding a
    /// `-2` only when two packages share one), so the id alone is enough. A server
    /// that reports `family` on /v1/models is believed over the name.
    static func family(forModelID id: String, declared: String?) -> ModelFamilySpec? {
        if let declared, let spec = families[declared] { return spec }
        if let spec = families[id] { return spec }
        // Strip a "-2" disambiguator, then any "tts-"/"asr-" prefix from older configs.
        var key = id
        if let dash = key.lastIndex(of: "-"), key[key.index(after: dash)...].allSatisfy(\.isNumber) {
            key = String(key[key.startIndex..<dash])
        }
        if let spec = families[key] { return spec }
        for (name, spec) in families where key.hasSuffix(name) || key.hasPrefix(name) {
            return spec
        }
        return nil
    }
